			if value != "" {
				for _, name := range f.Names() {

					if !filepath.IsAbs(value) && isc.Source() != "" {
						basePathAbs, err := filepath.Abs(isc.Source())
						if err != nil {
							return err
						}

						value = filepath.Join(filepath.Dir(basePathAbs), value)
					}

					_ = f.set.Set(name, value)
				}
			}
		}
	}
	return nil
}

